y) 	else 		return false 	end end  TinyHx.Radio = function (vec, radius, teamNum, teamType) 	local tbl = Heroes.InRadius(vec, radius, teamNum, teamType) 	if tbl ~= nil then 		return tbl 	else 		return {} 	end end  function TinyHx.TargetSettings(MyPlayerHero)   	local targetingRange = Menu.GetValue(TinyHx.optionTargetRange) 	local mousePos = Input.GetWorldCursorPos()  	local enemyTable = TinyHx.Radio(mousePos, targetingRange, Entity.GetTeamNum(MyPlayerHero), Enum.TeamType.TEAM_ENEMY) 		if #enemyTable < 1 then return end  	local nearestTarget = nil 	local distance = 99999  	for i, v in ipairs(enemyTable) do 		if v and Entity.IsHero(v) then 			if TinyHx.targetChecker(v) ~= nil then 				local enemyDist = (Entity.GetAbsOrigin(v) - mousePos):Length2D() 				if enemyDist < distance then 					nearestTarget = v 					distance = enemyDist 				end 			end 		end 	end  	return nearestTarget or nil  end   function TinyHx.targetChecker(genericEnemyEntity)  	local MyPlayerHero = Heroes.GetLocal()   	if genericEnemyEntity and not Entity.IsDormant(genericEnemyEntity) and not NPC.IsIllusion(genericEnemyEntity) and Entity.GetHealth(genericEnemyEntity) > 0 then  		if Menu.IsEnabled(TinyHx.optionTargetCheckAM) then 			if NPC.GetUnitName(genericEnemyEntity) == "npc_dota_hero_antimage" and NPC.HasItem(genericEnemyEntity, "item_ultimate_scepter", true) and NPC.HasModifier(genericEnemyEntity, "modifier_antimage_spell_shield") and Ability.IsReady(NPC.GetAbility(genericEnemyEntity, "antimage_spell_shield")) then 				return 			end 		end 		if Menu.IsEnabled(TinyHx.optionEnableLorb) then 			if NPC.HasModifier(genericEnemyEntity, "modifier_item_lotus_orb_active") then 				return 			end 		end 		if Menu.IsEnabled(TinyHx.optionEnableBmail) then 			if NPC.HasModifier(genericEnemyEntity, "modifier_item_blade_mail_reflect") and Entity.GetHealth(Heroes.GetLocal()) <= 0.25 * Entity.GetMaxHealth(Heroes.GetLocal()) then 				return 			end 		end 		if Menu.IsEnabled(TinyHx.optionTargetCheckNyx) then 			if NPC.HasModifier(genericEnemyEntity, "modifier_nyx_assassin_spiked_carapace") then 				return 			end 		end 		if Menu.IsEnabled(TinyHx.optionTargetCheckUrsa) then 			if NPC.HasModifier(genericEnemyEntity, "modifier_ursa_enrage") then 				return 			end 		end 		if Menu.IsEnabled(TinyHx.optionTargetCheckAbbadon) then 			if NPC.HasModifier(genericEnemyEntity, "modifier_abaddon_borrowed_time") then 				return 			end 		end 		if Menu.IsEnabled(TinyHx.optionTargetCheckDazzle) then 			if NPC.HasModifier(genericEnemyEntity, "modifier_dazzle_shallow_grave") and NPC.GetUnitName(MyPlayerHero) ~= "npc_dota_hero_axe" then 				return 			end 		end 		if NPC.HasModifier(genericEnemyEntity, "modifier_skeleton_king_reincarnation_scepter_active") then 			return 		end 		if NPC.HasModifier(genericEnemyEntity, "modifier_winter_wyvern_winters_curse") then 			return 		end  	return genericEnemyEntity 	end	 end  function TinyHx.AfterReady(sleep)  	if (os.clock() - TinyHx.After) >= sleep then 		return true 	end 	return false  end  function TinyHx.OnDraw() 	local MyPlayerHero = Heroes.GetLocal() 	if MyPlayerHero == nil or  NPC.GetUnitName(MyPlayerHero) ~= "npc_dota_hero_tiny" or not Entity.IsAlive(MyPlayerHero) then return end 	if not Menu.IsEnabled(TinyHx.optionLockTargetIndicator) or not Engine.IsInGame() then 	if TinyHx.Particle ~= 0 then             Particle.Destroy(TinyHx.Particle)		             TinyHx.Particle = 0 		end 	    return     end 	enemy = Input.GetNearestHeroToCursor(Entity.GetTeamNum(MyPlayerHero), Enum.TeamType.TEAM_ENEMY)     local enemyStatus = (enemy and enemy~= 0)     cursor_pos = Input.GetWorldCursorPos()     if enemy and enemy ~= 0 then     enemy_origin = Entity.GetAbsOrigin(enemy)      if (cursor_pos - enemy_origin):Length2D() > Menu.GetValue(TinyHx.optionTargetRange) then              Particle.Destroy(TinyHx.Particle)		 			TinyHx.Particle = 0             enemy = nil          return      end 	local curtime = GameRules.GetGameTime()	   	if Menu.GetValue(TinyHx.optionLockTargetParticle) < 2 then 		if TinyHx.LockedTarget ~= nil then 			if curtime > TinyHx.particleNextTime then 				if TinyHx.Particle > 0 then 					Particle.Destroy(TinyHx.Particle) 					TinyHx.Particle = 0 				end 	 				if Menu.GetValue(TinyHx.optionLockTargetParticle) == 0 then 					local sparkParticle = Particle.Create("particles/items_fx/aegis_resspawn_flash.vpcf") 					TinyHx.Particle = sparkParticle 			 					Particle.SetControlPoint(sparkParticle, 0, Entity.GetAbsOrigin(TinyHx.LockedTarget)) 				else 					local bloodParticle = Particle.Create("particles/items2_fx/soul_ring_blood.vpcf") 					TinyHx.Particle = bloodParticle 					Particle.SetControlPoint(bloodParticle, 0, Entity.GetAbsOrigin(TinyHx.LockedTarget)) 				end  	      		TinyHx.particleNextTime = curtime + 0.35 			end 		end 	else 		if (not TinyHx.LockedTarget or TinyHx.LockedTarget ~= TinyHx.ParticleTarget) and TinyHx.Particle > 0 then 			Particle.Destroy(TinyHx.Particle)			 			TinyHx.Particle = 0 			TinyHx.ParticleTarget = TinyHx.LockedTarget 		else 			if TinyHx.Particle == 0 and TinyHx.LockedTarget then 				local towerParticle = Particle.Create("particles/ui_mouseactions/range_finder_tower_aoe.vpcf", Enum.ParticleAttachment.PATTACH_INVALID, TinyHx.LockedTarget)	 				TinyHx.Particle = towerParticle 				TinyHx.ParticleTarget = TinyHx.LockedTarget			 			end 			if TinyHx.Particle > 0 then 				Particle.SetControlPoint(TinyHx.Particle, 2, Entity.GetOrigin(MyPlayerHero)) 				Particle.SetControlPoint(TinyHx.Particle, 6, Vector(1, 0, 0)) 				Particle.SetControlPoint(TinyHx.Particle, 7, Entity.GetOrigin(TinyHx.ParticleTarget)) 			end 		end 	end end end  function TinyHx.heroCanCastSpells(MyPlayerHero, enemy)  	if not MyPlayerHero then return false end 	if not TinyHx.AfterisAlive(MyPlayerHero) then return false end  	if NPC.IsSilenced(MyPlayerHero) then return false end  	if NPC.IsStunned(MyPlayerHero) then return false end 	if NPC.HasModifier(MyPlayerHero, "modifier_bashed") then return false end 	if NPC.HasState(MyPlayerHero, 