nyHx.optionSilence) and orchid and Ability.IsCastable(orchid,myMana)  and NPC.IsEntityInRange(enemy, MyPlayerHero, Ability.GetCastRange(orchid) - 10) then Ability.CastTarget(orchid, enemy) end 	if not NPC.IsLinkensProtected(enemy) and Menu.IsEnabled(TinyHx.optionbloodthorn) and bloodthorn and Ability.IsCastable(bloodthorn, myMana) and NPC.IsEntityInRange(enemy, MyPlayerHero, Ability.GetCastRange(bloodthorn) - 10) then Ability.CastTarget(bloodthorn, enemy) return end 	if not NPC.IsLinkensProtected(enemy) and Menu.IsEnabled(TinyHx.optionEnableDiffusal) and diffusal and  Ability.IsCastable(diffusal, 0) and NPC.IsEntityInRange(enemy, MyPlayerHero, Ability.GetCastRange(diffusal) - 10) then Ability.CastTarget(diffusal, enemy) end 	if not NPC.IsLinkensProtected(enemy) and Menu.IsEnabled(TinyHx.optionEnableRod) and rod and Ability.IsCastable(rod,myMana)  and NPC.IsEntityInRange(enemy, MyPlayerHero, Ability.GetCastRange(rod) - 10) then Ability.CastTarget(rod, enemy) end 	if Menu.IsEnabled(TinyHx.optionEnableMedallion) and medallion  and Ability.IsCastable(medallion, myMana)  and NPC.IsEntityInRange(enemy, MyPlayerHero, Ability.GetCastRange(medallion) - 10) then Ability.CastTarget(medallion, enemy) end 	if Menu.IsEnabled(TinyHx.optionEnableSolar) and solar and  Ability.IsCastable(solar, myMana) then Ability.CastTarget(solar, enemy) end 	 	if not NPC.IsLinkensProtected(enemy) and Menu.IsEnabled(TinyHx.optionEnableHex) and hex and Ability.IsCastable(hex, myMana) and NPC.IsEntityInRange(enemy, MyPlayerHero, Ability.GetCastRange(hex) - 10) then Ability.CastTarget(hex, enemy); return end 	if Menu.IsEnabled(TinyHx.optionBkb) and bkb and Ability.IsCastable(bkb, myMana) and Ability.IsReady(bkb) then Ability.CastNoTarget(bkb) return end 	if not NPC.IsLinkensProtected(enemy) and Menu.IsEnabled(TinyHx.optionNullifier) and nullifier and Ability.IsCastable(nullifier, myMana)  and NPC.IsEntityInRange(enemy, MyPlayerHero, Ability.GetCastRange(nullifier) - 10)then Ability.CastTarget(nullifie